SELECT 'Counts' AS Audit, (SELECT COUNT(*) FROM LeaveTypes) AS ExistingTypes,(SELECT COUNT(*) FROM LeaveDefinitions) AS Definitions,(SELECT COUNT(*) FROM LeavePolicies) AS Policies,(SELECT COUNT(*) FROM LeaveTypeMappings) AS Mappings;
SELECT t.LeaveTypeID,t.Name,t.OrganisationID,t.MigratedLeaveDefinitionID FROM LeaveTypes t ORDER BY t.LeaveTypeID;
SELECT * FROM LeaveTypeMappings;
SELECT LeaveDefinitionID,Code,Name,OwnerOrganisationID,IsGlobal,IsActive FROM LeaveDefinitions;
SELECT LeavePolicyID,LeaveDefinitionID,OrganisationID,Name,IsActive,EffectiveFrom,EffectiveTo FROM LeavePolicies;
SELECT LeaveTypeID,LeaveDefinitionID,COUNT(*) AS Balances,SUM(RemainingDays) AS Balance FROM JobLeaveTypes GROUP BY LeaveTypeID,LeaveDefinitionID;
SELECT OBJECT_NAME(f.parent_object_id) AS Dependent,c.name AS ColumnName,OBJECT_NAME(f.referenced_object_id) AS Principal, rc.name AS PrincipalColumn FROM sys.foreign_key_columns f JOIN sys.columns c ON c.object_id=f.parent_object_id AND c.column_id=f.parent_column_id JOIN sys.columns rc ON rc.object_id=f.referenced_object_id AND rc.column_id=f.referenced_column_id WHERE OBJECT_NAME(f.referenced_object_id) IN ('LeaveTypes','LeaveDefinitions');
SELECT JobLeaveTypeID,JobID,LeaveTypeID,LeaveDefinitionID,RemainingDays,IsValid,IsLeaveInfoUpdated FROM JobLeaveTypes WHERE LeaveDefinitionID IS NOT NULL; SELECT m.LeaveDefinitionID,m.LegacyLeaveTypeID,j.JobID,COUNT(*) AS DuplicateAssignments FROM LeaveTypeMappings m JOIN JobLeaveTypes j ON j.LeaveTypeID=m.LegacyLeaveTypeID OR j.LeaveDefinitionID=m.LeaveDefinitionID WHERE j.IsValid=1 GROUP BY m.LeaveDefinitionID,m.LegacyLeaveTypeID,j.JobID HAVING COUNT(*)>1;
SELECT 'Constraint' AS Kind,name,OBJECT_NAME(parent_object_id) AS TableName FROM sys.objects WHERE parent_object_id IN (OBJECT_ID('dbo.LeaveTypes'),OBJECT_ID('dbo.LA_JobTypeLeaveAccrualRules')); SELECT 'Index' AS Kind,name,OBJECT_NAME(object_id) AS TableName FROM sys.indexes WHERE object_id IN(OBJECT_ID('dbo.LeaveTypes'),OBJECT_ID('dbo.JobLeaveTypes'),OBJECT_ID('dbo.LeavePolicies'));
